/* =====================================================================
 * Librería común de los flujos. El generador (scripts/build.mjs) la
 * antepone al código de cada nodo Code, así que aquí se puede usar lo
 * que ofrece n8n: $env, $now (luxon en Europe/Madrid) y DateTime.
 * ===================================================================== */

const CFG = (() => {
  const list = (s) => String(s || '').split(',').map((x) => x.trim()).filter(Boolean)
  const num = (v, d) => (Number.isFinite(Number(v)) && String(v).trim() !== '' ? Number(v) : d)
  return {
    nombre: $env.REST_NOMBRE || 'Restaurante',
    telefono: $env.REST_TELEFONO || '',
    direccion: $env.REST_DIRECCION || '',
    remitente: $env.REST_EMAIL_REMITENTE || 'reservas@example.com',
    dueno: $env.REST_EMAIL_DUENO || '',
    aforo: { comida: num($env.REST_AFORO_COMIDA, 40), cena: num($env.REST_AFORO_CENA, 40) },
    franja: num($env.REST_ENTRADAS_FRANJA, 16),
    horas: { comida: list($env.REST_HORAS_COMIDA), cena: list($env.REST_HORAS_CENA) },
    cerrado: list($env.REST_DIAS_CERRADO).map(Number),
    maxPersonas: num($env.REST_MAX_PERSONAS, 10),
    antelacionMin: num($env.REST_ANTELACION_MIN, 60),
    diasMax: num($env.REST_DIAS_MAX, 60),
    resena: $env.REST_URL_RESENA || '',
    clavePanel: $env.REST_CLAVE_PANEL || '',
    claveAgente: $env.REST_CLAVE_AGENTE || '',
    url: String($env.WEBHOOK_URL || '').replace(/\/$/, ''),
  }
})()

/** Estados que ocupan sitio. */
const OCUPAN = ['confirmada', 'llegada']

const hoy = (dias = 0) => $now.plus({ days: dias }).toFormat('yyyy-MM-dd')

function turnoDe(hora) {
  if (CFG.horas.comida.includes(hora)) return 'comida'
  if (CFG.horas.cena.includes(hora)) return 'cena'
  return null
}

function fechaLarga(fecha) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  return d.isValid ? d.setLocale('es').toFormat("cccc d 'de' LLLL") : fecha
}

/** Filas reales de una Data Table (la consulta vacía devuelve un único item sin id). */
function filas(items) {
  return items.map((i) => i.json).filter((r) => r && r.id !== undefined)
}

/**
 * Disponibilidad de un día. Dos límites a la vez:
 *  - aforo del turno (comensales totales en comida o cena),
 *  - ritmo de entradas: comensales que pueden llegar en la misma franja de 30 min.
 * Las horas que ya han pasado (más la antelación mínima) no se ofrecen.
 */
function disponibilidad(fecha, reservas, personas = 2, { ignorarAntelacion = false } = {}) {
  const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
  if (!/^\d{4}-\d{2}-\d{2}$/.test(fecha) || !d.isValid) return { ok: false, motivo: 'Fecha no válida.' }
  if (d.startOf('day') < $now.startOf('day')) return { ok: false, motivo: 'Esa fecha ya ha pasado.' }
  if (d.startOf('day') > $now.plus({ days: CFG.diasMax }).startOf('day')) {
    return { ok: false, motivo: `Solo se puede reservar con hasta ${CFG.diasMax} días de antelación.` }
  }
  if (CFG.cerrado.includes(d.weekday)) return { ok: true, cerrado: true, motivo: `${CFG.nombre} cierra ese día.`, horas: [] }

  const activas = reservas.filter((r) => r.fecha === fecha && OCUPAN.includes(r.estado))
  const porTurno = { comida: 0, cena: 0 }
  const porHora = {}
  for (const r of activas) {
    const p = Number(r.personas) || 0
    if (porTurno[r.turno] !== undefined) porTurno[r.turno] += p
    porHora[r.hora] = (porHora[r.hora] || 0) + p
  }
  const limite = $now.plus({ minutes: ignorarAntelacion ? 0 : CFG.antelacionMin })
  const horas = []
  for (const turno of ['comida', 'cena']) {
    for (const hora of CFG.horas[turno]) {
      const [h, m] = hora.split(':').map(Number)
      const momento = d.set({ hour: h, minute: m, second: 0, millisecond: 0 })
      const libre = Math.max(0, Math.min(CFG.aforo[turno] - porTurno[turno], CFG.franja - (porHora[hora] || 0)))
      const pasada = momento < limite
      horas.push({ hora, turno, libre, disponible: !pasada && libre >= personas, pasada })
    }
  }
  return {
    ok: true,
    cerrado: false,
    fecha,
    fechaTexto: fechaLarga(fecha),
    horas,
    ocupacion: {
      comida: { comensales: porTurno.comida, aforo: CFG.aforo.comida },
      cena: { comensales: porTurno.cena, aforo: CFG.aforo.cena },
    },
  }
}

/** Horas alternativas cercanas (mismo día y días siguientes) para quien no encuentra sitio. */
function alternativas(disp, hora, personas) {
  if (!disp.ok || disp.cerrado) return []
  const [h, m] = (hora || '00:00').split(':').map(Number)
  const minutos = (x) => {
    const [a, b] = x.split(':').map(Number)
    return a * 60 + b
  }
  return disp.horas
    .filter((x) => x.disponible && x.libre >= personas)
    .sort((a, b) => Math.abs(minutos(a.hora) - (h * 60 + m)) - Math.abs(minutos(b.hora) - (h * 60 + m)))
    .slice(0, 3)
    .map((x) => x.hora)
}

function limpiarTexto(v, max) {
  return String(v ?? '').replace(/[\u0000-\u001f<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max)
}

function normalizarTelefono(t) {
  const d = String(t ?? '').replace(/[^\d+]/g, '')
  if (/^[6789]\d{8}$/.test(d)) return '+34' + d
  if (/^0034\d{9}$/.test(d)) return '+' + d.slice(2)
  if (/^\+\d{8,15}$/.test(d)) return d
  return ''
}

/** Valida y normaliza los datos de una reserva. */
function validarReserva(b) {
  const errores = []
  const datos = {
    nombre: limpiarTexto(b.nombre, 80),
    email: String(b.email ?? '').trim().toLowerCase().slice(0, 120),
    telefono: normalizarTelefono(b.telefono),
    fecha: String(b.fecha ?? '').trim(),
    hora: String(b.hora ?? '').trim(),
    personas: Math.floor(Number(b.personas)),
    notas: limpiarTexto(b.notas, 300),
  }
  if (datos.nombre.length < 2) errores.push('Indica tu nombre.')
  if (!datos.telefono) errores.push('Indica un teléfono válido.')
  if (datos.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(datos.email)) errores.push('El email no es válido.')
  if (!/^\d{4}-\d{2}-\d{2}$/.test(datos.fecha)) errores.push('Elige una fecha.')
  if (!turnoDe(datos.hora)) errores.push('Elige una hora.')
  if (!(datos.personas >= 1)) errores.push('Indica el número de personas.')
  else if (datos.personas > CFG.maxPersonas) {
    errores.push(`Para grupos de más de ${CFG.maxPersonas} personas llámanos${CFG.telefono ? ' al ' + CFG.telefono : ''}.`)
  }
  return { ok: errores.length === 0, errores, datos }
}

const crypto = require('crypto')
const nuevoToken = () => crypto.randomBytes(18).toString('base64url')
/** Código corto para decirlo por teléfono: sin 0/O ni 1/I. */
function nuevoCodigo() {
  const abc = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
  let s = ''
  for (const b of crypto.randomBytes(6)) s += abc[b % abc.length]
  return s
}

const enlace = (token) => `${CFG.url}/webhook/reserva?t=${encodeURIComponent(token)}`
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c])

/* ----------------------------------------------------------- plantillas */

function emailHtml({ titulo, intro, filas: datos = [], botones = [], pie = '' }) {
  const rows = datos
    .map(([k, v]) => `<tr><td style="padding:6px 0;color:#6b7280;font-size:14px;width:120px">${esc(k)}</td><td style="padding:6px 0;font-size:15px;color:#111827;font-weight:600">${esc(v)}</td></tr>`)
    .join('')
  const btns = botones
    .map(
      (b) =>
        `<a href="${esc(b.url)}" style="display:inline-block;margin:6px 8px 0 0;padding:12px 20px;border-radius:10px;text-decoration:none;font-weight:600;font-size:15px;${
          b.secundario ? 'background:#f3f4f6;color:#111827' : 'background:#111827;color:#ffffff'
        }">${esc(b.texto)}</a>`,
    )
    .join('')
  return `<!doctype html><html lang="es"><body style="margin:0;background:#f5f5f4;font-family:Arial,Helvetica,sans-serif">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="padding:24px 12px"><tr><td align="center">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="max-width:520px;background:#ffffff;border-radius:16px;padding:28px">
<tr><td style="font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:#9ca3af">${esc(CFG.nombre)}</td></tr>
<tr><td style="padding-top:8px;font-size:24px;font-weight:700;color:#111827">${esc(titulo)}</td></tr>
<tr><td style="padding-top:10px;font-size:15px;line-height:1.55;color:#374151">${intro}</td></tr>
${rows ? `<tr><td style="padding-top:16px"><table role="presentation" width="100%" style="border-top:1px solid #eee;border-bottom:1px solid #eee;padding:8px 0">${rows}</table></td></tr>` : ''}
${btns ? `<tr><td style="padding-top:18px">${btns}</td></tr>` : ''}
<tr><td style="padding-top:22px;font-size:13px;line-height:1.5;color:#9ca3af">${pie || [CFG.direccion, CFG.telefono].filter(Boolean).map(esc).join(' · ')}</td></tr>
</table></td></tr></table></body></html>`
}

function datosReserva(r) {
  return [
    ['Fecha', fechaLarga(r.fecha)],
    ['Hora', r.hora],
    ['Personas', String(r.personas)],
    ['Nombre', r.nombre],
    ['Código', r.codigo],
  ].concat(r.notas ? [['Notas', r.notas]] : [])
}

const CSS = `*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,sans-serif;background:#f5f3ef;color:#1c1917}
.wrap{max-width:560px;margin:0 auto;padding:28px 16px 48px}.card{background:#fff;border-radius:20px;padding:24px;box-shadow:0 1px 2px rgba(0,0,0,.04),0 8px 30px rgba(0,0,0,.05)}
h1{font-size:28px;margin:0 0 6px;letter-spacing:-.02em}.muted{color:#78716c}.brand{font-size:12px;letter-spacing:.12em;text-transform:uppercase;color:#a8a29e;margin-bottom:6px}
.btn{display:inline-block;border:0;border-radius:12px;padding:13px 20px;font-size:16px;font-weight:600;cursor:pointer;text-decoration:none;text-align:center}
.btn-primary{background:#1c1917;color:#fff}.btn-ghost{background:#f5f5f4;color:#1c1917}.btn-danger{background:#fee2e2;color:#991b1b}
dl{display:grid;grid-template-columns:110px 1fr;gap:8px 12px;margin:18px 0;padding:16px 0;border-top:1px solid #eee;border-bottom:1px solid #eee}dt{color:#78716c}dd{margin:0;font-weight:600}
.ok{color:#15803d}.bad{color:#b91c1c}`

function pagina(titulo, cuerpo) {
  return `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">
<title>${esc(titulo)} · ${esc(CFG.nombre)}</title><style>${CSS}</style></head><body><div class="wrap"><div class="brand">${esc(CFG.nombre)}</div>${cuerpo}</div></body></html>`
}

function respuesta(status, body) {
  return [{ json: { status, body } }]
}

/* ---- Pintar panel ---- */
const q = $('GET /panel').first().json.query || {}
if (!CFG.clavePanel || q.clave !== CFG.clavePanel) {
  return [{ json: { status: 401, html: pagina('Panel', '<div class="card"><h1>Panel del restaurante</h1><form method="get"><label>Clave</label><input name="clave" type="password" autofocus style="width:100%;padding:12px;border:1px solid #ddd;border-radius:10px;margin:8px 0"><button class="btn btn-primary">Entrar</button></form></div>') } }]
}
const fecha = /^\d{4}-\d{2}-\d{2}$/.test(q.fecha || '') ? q.fecha : hoy()
const d = DateTime.fromISO(fecha, { zone: $now.zoneName })
const datos = {
  clave: q.clave, fecha, hoy: hoy(), fechaTexto: fechaLarga(fecha), cerrado: CFG.cerrado.includes(d.weekday), aforo: CFG.aforo,
  reservas: filas($input.all()).map((r) => ({ token: r.token, codigo: r.codigo, nombre: r.nombre, telefono: r.telefono, hora: r.hora, turno: r.turno, personas: Number(r.personas), notas: r.notas, estado: r.estado, asistencia: r.asistencia, origen: r.origen })),
}
const html = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\" />\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\" />\n<meta name=\"robots\" content=\"noindex\" />\n<title>Panel · __NOMBRE__</title>\n<style>\n  *{box-sizing:border-box}\n  :root{--bg:#111214;--card:#1a1c1f;--line:#2a2d32;--ink:#f2f2f0;--mute:#9a9ea6;--acc:#e8a33d;--ok:#4caf6d;--bad:#e5534b;--blue:#5aa2ff}\n  body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\n  .wrap{max-width:1100px;margin:0 auto;padding:18px 16px 60px}\n  header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}\n  h1{margin:0;font-size:22px}\n  .nav{display:flex;gap:6px;align-items:center}\n  .nav a,.nav button{background:var(--card);border:1px solid var(--line);color:var(--ink);border-radius:10px;padding:8px 12px;text-decoration:none;font:inherit;cursor:pointer}\n  .nav input{background:var(--card);border:1px solid var(--line);color:var(--ink);border-radius:10px;padding:7px 10px;font:inherit;color-scheme:dark}\n  .kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin:16px 0}\n  .kpi{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px 14px}\n  .kpi b{display:block;font-size:26px}\n  .kpi small{color:var(--mute)}\n  .bar{height:6px;border-radius:9px;background:var(--line);margin-top:8px;overflow:hidden}\n  .bar i{display:block;height:100%;background:var(--acc)}\n  h2{font-size:14px;letter-spacing:.12em;text-transform:uppercase;color:var(--mute);margin:22px 0 8px}\n  table{width:100%;border-collapse:collapse;background:var(--card);border:1px solid var(--line);border-radius:14px;overflow:hidden}\n  th,td{text-align:left;padding:10px 12px;border-bottom:1px solid var(--line);vertical-align:top}\n  th{font-size:12px;color:var(--mute);font-weight:600;text-transform:uppercase;letter-spacing:.06em}\n  tr:last-child td{border-bottom:0}\n  tr.cancelada,tr.no_show{opacity:.45}\n  tr.llegada td:first-child{box-shadow:inset 3px 0 0 var(--ok)}\n  .hora{font-weight:800;font-size:17px}\n  .pax{font-weight:800;font-size:17px}\n  .tag{display:inline-block;font-size:11px;font-weight:700;border-radius:999px;padding:2px 8px;margin:2px 4px 0 0;background:var(--line);color:var(--mute)}\n  .tag.ok{background:rgba(76,175,109,.18);color:var(--ok)}\n  .tag.warn{background:rgba(232,163,61,.18);color:var(--acc)}\n  .tag.bad{background:rgba(229,83,75,.18);color:var(--bad)}\n  .tag.blue{background:rgba(90,162,255,.18);color:var(--blue)}\n  .notas{color:var(--acc);font-size:13px;margin-top:4px}\n  a.tel{color:var(--ink)}\n  .acc{display:flex;flex-wrap:wrap;gap:6px}\n  .acc button{border:1px solid var(--line);background:transparent;color:var(--ink);border-radius:9px;padding:6px 10px;font:600 13px system-ui;cursor:pointer}\n  .acc button.ok{border-color:var(--ok);color:var(--ok)}\n  .acc button.bad{border-color:var(--bad);color:var(--bad)}\n  .vacio{color:var(--mute);padding:18px;background:var(--card);border:1px dashed var(--line);border-radius:14px}\n  form.nueva{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px;background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px}\n  form.nueva input,form.nueva select{background:var(--bg);border:1px solid var(--line);color:var(--ink);border-radius:9px;padding:9px;font:inherit;color-scheme:dark}\n  form.nueva button{background:var(--acc);color:#1b1305;border:0;border-radius:9px;font-weight:800;cursor:pointer}\n  #toast{position:fixed;bottom:16px;left:50%;transform:translateX(-50%);background:#fff;color:#111;border-radius:10px;padding:10px 16px;font-weight:600;display:none}\n  @media (max-width:760px){thead{display:none}tr{display:grid;grid-template-columns:70px 1fr;padding:6px 0}td{border:0;padding:4px 12px}td.c-hora{grid-row:span 3}}\n  @media print{.nav,.acc,form.nueva,#toast{display:none}body{background:#fff;color:#000}table,.kpi{border-color:#ccc;background:#fff}}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n  <header>\n    <div><div style=\"color:var(--mute);font-size:12px;letter-spacing:.12em;text-transform:uppercase\">__NOMBRE__ · panel</div><h1 id=\"titulo\"></h1></div>\n    <div class=\"nav\">\n      <a id=\"ant\" href=\"#\">‹</a><a id=\"hoyBtn\" href=\"#\">Hoy</a><a id=\"sig\" href=\"#\">›</a>\n      <input type=\"date\" id=\"fecha\" aria-label=\"Fecha\" />\n      <button onclick=\"print()\">Imprimir</button>\n    </div>\n  </header>\n  <section class=\"kpis\" id=\"kpis\"></section>\n  <h2>Añadir reserva (teléfono o en persona)</h2>\n  <form class=\"nueva\" id=\"nueva\">\n    <input name=\"hora\" placeholder=\"Hora (13:30)\" required pattern=\"\\d{2}:\\d{2}\" />\n    <input name=\"personas\" type=\"number\" min=\"1\" placeholder=\"Personas\" required />\n    <input name=\"nombre\" placeholder=\"Nombre\" required />\n    <input name=\"telefono\" placeholder=\"Teléfono\" required />\n    <input name=\"email\" type=\"email\" placeholder=\"Email (opcional)\" />\n    <input name=\"notas\" placeholder=\"Notas / alergias\" />\n    <button>Reservar</button>\n  </form>\n  <div id=\"lista\"></div>\n</div>\n<div id=\"toast\" role=\"status\"></div>\n<script>\nconst D = __DATA__;\nconst $ = (id) => document.getElementById(id);\nconst esc = (s) => String(s ?? '').replace(/[&<>\"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;' })[c]);\nconst tel = (t) => { const m = /^\\+34(\\d{3})(\\d{2})(\\d{2})(\\d{2})$/.exec(t || ''); return m ? m[1] + ' ' + m[2] + ' ' + m[3] + ' ' + m[4] : (t || ''); };\nconst go = (f) => { location.href = '?clave=' + encodeURIComponent(D.clave) + '&fecha=' + f; };\nconst shift = (n) => { const d = new Date(D.fecha + 'T12:00:00'); d.setDate(d.getDate() + n); return d.toISOString().slice(0, 10); };\n$('ant').onclick = (e) => { e.preventDefault(); go(shift(-1)); };\n$('sig').onclick = (e) => { e.preventDefault(); go(shift(1)); };\n$('hoyBtn').onclick = (e) => { e.preventDefault(); go(D.hoy); };\n$('fecha').value = D.fecha; $('fecha').onchange = (e) => go(e.target.value);\n$('titulo').textContent = D.fechaTexto.charAt(0).toUpperCase() + D.fechaTexto.slice(1) + (D.cerrado ? ' · cerrado' : '');\n\nfunction toast(t) { const el = $('toast'); el.textContent = t; el.style.display = 'block'; setTimeout(() => el.style.display = 'none', 2200); }\n\nfunction kpis() {\n  const act = D.reservas.filter((r) => ['confirmada', 'llegada'].includes(r.estado));\n  const pax = (t) => act.filter((r) => r.turno === t).reduce((a, r) => a + r.personas, 0);\n  const k = (titulo, valor, sub, pct) => '<div class=\"kpi\"><small>' + titulo + '</small><b>' + valor + '</b><small>' + sub + '</small>' + (pct !== undefined ? '<div class=\"bar\"><i style=\"width:' + Math.min(100, pct) + '%\"></i></div>' : '') + '</div>';\n  $('kpis').innerHTML =\n    k('Comida', pax('comida') + ' / ' + D.aforo.comida, 'comensales', (pax('comida') / D.aforo.comida) * 100) +\n    k('Cena', pax('cena') + ' / ' + D.aforo.cena, 'comensales', (pax('cena') / D.aforo.cena) * 100) +\n    k('Reservas', act.length, (() => { const c = act.filter((r) => r.asistencia === 'confirmada').length; return c + (c === 1 ? ' ha' : ' han') + ' confirmado asistencia'; })()) +\n    k('Llegadas', D.reservas.filter((r) => r.estado === 'llegada').length, D.reservas.filter((r) => r.estado === 'no_show').length + ' no vinieron · ' + D.reservas.filter((r) => r.estado === 'cancelada').length + ' canceladas');\n}\n\nfunction fila(r) {\n  const tags = [];\n  if (r.asistencia === 'confirmada') tags.push('<span class=\"tag ok\">confirmó asistencia</span>');\n  if (r.origen && r.origen !== 'web') tags.push('<span class=\"tag blue\">' + esc(r.origen) + '</span>');\n  if (r.personas >= 6) tags.push('<span class=\"tag warn\">grupo</span>');\n  const est = { confirmada: '', llegada: '<span class=\"tag ok\">llegó</span>', no_show: '<span class=\"tag bad\">no vino</span>', cancelada: '<span cl